# ------ JSON-RPC --------------

class ExcRpc(Exception):
    pass


class ErrRpcTimeout(ExcRpc):
    pass


class ErrRpcMethodAlreadyRegistered(ExcRpc):
    def __init__(self, rpc_public_name, registered_method, method):
        self.rpc_public_name = rpc_public_name
        self.registered_method = registered_method
        self.method = method

    def __str__(self):
        return "'%s' maps to %s, can't register %s" % (self.rpc_public_name, self.registered_method, self.method)


class RpcServerStop(ExcRpc):
    pass


class RpcRequestAlreadyWaiting(ExcRpc):
    def __init__(self, request):
        super(RpcRequestAlreadyWaiting, self).__init__()
        self.request = request

    def __str__(self):
        return "Rpc request '%s' already waiting for response)" % self.request


class RpcRequestOtherWaiting(ExcRpc):
    def __init__(self, request, waiting_request):
        super(RpcRequestOtherWaiting, self).__init__()
        self.request = request
        self.waiting_request = waiting_request

    def __str__(self):
        return "Can't put request '%s' in waiting room - '%s' already waiting on same response queue)" % (self.request, self.waiting_request)
